// Parse and validate sensor data
const message = $input.first().json;

const parseTopicParts = (topic) => {
  const parts = topic.split('/');
  return {
    category: parts[1] || 'unknown',
    location: parts[2] || 'unknown',
    deviceId: parts[3] || 'unknown',
    metric: parts[4] || 'data'
  };
};

const topicParts = parseTopicParts(message.topic);

const parsedData = {
  device_id: topicParts.deviceId,
  location: topicParts.location,
  category: topicParts.category,
  metric_type: topicParts.metric,
  raw_value: message.payload,
  timestamp: message.timestamp || new Date().toISOString(),
  received_at: new Date().toISOString()
};

// Parse payload based on type
if (typeof message.payload === 'object') {
  parsedData.temperature = message.payload.temperature;
  parsedData.humidity = message.payload.humidity;
  parsedData.pressure = message.payload.pressure;
  parsedData.battery_level = message.payload.battery;
  parsedData.signal_strength = message.payload.rssi;
} else {
  parsedData.value = message.payload;
}

return { json: parsedData };

// Validate sensor readings and detect anomalies
const data = $input.first().json;

// Define normal ranges
const thresholds = {
  temperature: { min: -10, max: 50, critical_low: 0, critical_high: 40 },
  humidity: { min: 0, max: 100, critical_low: 20, critical_high: 80 },
  pressure: { min: 950, max: 1050, critical_low: 980, critical_high: 1030 },
  battery_level: { min: 0, max: 100, critical_low: 20, critical_high: 100 }
};

const alerts = [];
const status = {
  overall: 'normal',
  issues: []
};

// Check each metric
Object.keys(thresholds).forEach(metric => {
  if (data[metric] !== undefined) {
    const value = parseFloat(data[metric]);
    const threshold = thresholds[metric];

    if (value < threshold.min || value > threshold.max) {
      status.overall = 'error';
      status.issues.push(`${metric} out of bounds: ${value}`);
      alerts.push({
        severity: 'critical',
        metric: metric,
        value: value,
        message: `${metric} reading ${value} is outside acceptable range [${threshold.min}, ${threshold.max}]`
      });
    } else if (value < threshold.critical_low || value > threshold.critical_high) {
      if (status.overall === 'normal') status.overall = 'warning';
      status.issues.push(`${metric} in warning zone: ${value}`);
      alerts.push({
        severity: 'warning',
        metric: metric,
        value: value,
        message: `${metric} reading ${value} is in warning zone`
      });
    }
  }
});

// Battery alert
if (data.battery_level && data.battery_level < 20) {
  alerts.push({
    severity: 'warning',
    metric: 'battery',
    value: data.battery_level,
    message: `Low battery: ${data.battery_level}%`
  });
}

const validatedData = {
  ...data,
  status: status.overall,
  issues: status.issues,
  alerts: alerts,
  has_alerts: alerts.length > 0,
  validated_at: new Date().toISOString()
};

return { json: validatedData };

// Format alert notification
const data = $input.first().json;
const alert = data.alerts;

const severityEmoji = {
  'critical': '🔴',
  'warning': '🟡',
  'info': 'ℹ️'
};

const notification = {
  title: `${severityEmoji[alert.severity]} IoT Device Alert`,
  message: `*Device:* ${data.device_id}\n*Location:* ${data.location}\n*Alert:* ${alert.message}\n*Status:* ${data.status}\n*Time:* ${new Date(data.timestamp).toLocaleString()}`,
  severity: alert.severity,
  device_id: data.device_id,
  location: data.location,
  metric: alert.metric,
  value: alert.value
};

return { json: notification };

