// Trigger automated response actions
const data = $input.first().json;
const actions = [];

// Define automated responses based on conditions
if (data.temperature && data.temperature > 35) {
  actions.push({
    action_type: 'mqtt_publish',
    topic: `actuators/${data.location}/${data.device_id}/cooling`,
    payload: { command: 'activate', intensity: 'high' },
    reason: 'High temperature detected'
  });
}

if (data.humidity && data.humidity > 70) {
  actions.push({
    action_type: 'mqtt_publish',
    topic: `actuators/${data.location}/${data.device_id}/dehumidifier`,
    payload: { command: 'activate' },
    reason: 'High humidity detected'
  });
}

if (data.battery_level && data.battery_level < 15) {
  actions.push({
    action_type: 'mqtt_publish',
    topic: `devices/${data.device_id}/power`,
    payload: { command: 'low_power_mode', enabled: true },
    reason: 'Critical battery level'
  });
}

return actions.map(action => ({ json: action }));
